rule.example:

// Violation: Single argument on multiple lines
String result = processValue(
	value
);

// Valid: Single argument on one line
String result = processValue(value);


// Valid: List declaration as argument (excluded from rule)
processList(new List<String>{
	'item1',
	'item2'
});

// Valid: Map declaration as argument (excluded from rule)
processMap(new Map<String, String>{
	'key1' => 'value1',
	'key2' => 'value2'
});

// Valid: Set declaration as argument (excluded from rule)
processSet(new Set<String>{
	'item1',
	'item2'
});


// Valid: Builder pattern (excluded from rule)
ClassName instance = new ClassName()
	.withBuilderArg(2);

// Valid: Builder pattern with multiple chained calls
Builder builder = new Builder()
	.setName('John')
	.setAge(30)
	.setEmail('john@example.com');

// Valid: Method chaining (excluded from rule)
String result = getObject()
	.processValue(value);


// Valid: First argument is a simple variable (not a method call or new object)
String id = '12345';
String name = 'John';
Integer num = 42;
Boolean flag = true;
Decimal price = 99.99;
Date today = Date.today();
processRecord(id);
calculateResult(num);
updateUser(name);
setFlag(flag);
applyDiscount(price);
scheduleTask(today);


// Valid: First argument is a method call (excluded from rule)
String result = processValue(getId());
Integer count = calculate(getNumber());
Boolean active = checkStatus(getRecord());

// Valid: First argument is a new object (excluded from rule)
String result = processValue(new MyClass());
Integer count = calculate(new Counter());
